def serialize(node):
    if node is None:
        return '#'
    return f',{node.val},' + serialize(node.left) + serialize(node.right)   # markers disambiguate structure

def is_subtree_brute(root, sub_root):
    return serialize(sub_root) in serialize(root)              # substring check on serialized forms

