def is_same_tree(a, b):
    if a is None and b is None:
        return True
    if a is None or b is None:
        return False
    return a.val == b.val and is_same_tree(a.left, b.left) and is_same_tree(a.right, b.right)

def is_subtree(root, sub_root):
    if root is None:
        return False
    if is_same_tree(root, sub_root):                    # try an exact match rooted HERE
        return True
    return is_subtree(root.left, sub_root) or is_subtree(root.right, sub_root)   # or search deeper

